/** Explicit local QA providers. Never loaded on the published hostname. */
export function testProviders(show){let serial=0;return {ads:{available:true,test:true,async showRewarded(placement){const outcome=await show('ad');if(outcome==='failure')throw Error('Test failure');return {completed:outcome==='success',rewardId:`test-ad:${Date.now()}:${++serial}`,placement};}},purchases:{available:true,test:true,async purchase(productId){const outcome=await show('purchase');if(outcome==='failure')throw Error('Test failure');return {verified:outcome==='success',cancelled:outcome==='cancel',productId,transactionId:`test-purchase:${Date.now()}:${++serial}`};}}};}
